      // Add customer order to order management system
      async addCustomerOrderToManagement(customerOrderId) {
        console.log(`\u{1F4CB} [ORDER MANAGEMENT] Adding customer order ${customerOrderId} to management system`);
        const existing = await this.getOrderManagementByCustomerOrderId(customerOrderId);
        if (existing) {
          console.log(`\u{1F4CB} [ORDER MANAGEMENT] Order ${customerOrderId} already exists in management system`);
          return existing;
        }
        const [customerOrder] = await db.select({
          paymentMethod: customerOrders.paymentMethod,
          orderNumber: customerOrders.orderNumber,
          paymentStatus: customerOrders.paymentStatus,
          deliveryMethod: customerOrders.deliveryMethod,
          vehicleType: customerOrders.vehicleType
        }).from(customerOrders).where(eq11(customerOrders.id, customerOrderId));
        if (!customerOrder) {
          throw new Error(`Customer order ${customerOrderId} not found`);
        }
        console.log(`\u{1F4E6} [ORDER MANAGEMENT] Customer order delivery: ${customerOrder.deliveryMethod}, vehicle: ${customerOrder.vehicleType}`);
        let initialStatus = "pending";
        if ((customerOrder.paymentMethod === "wallet_full" || customerOrder.paymentMethod === "wallet_partial") && customerOrder.paymentStatus === "paid") {
          initialStatus = "payment_uploaded";
          console.log(`\u{1F4B0} [WALLET ORDER] Setting wallet order ${customerOrder.orderNumber} to payment_uploaded status for financial review`);
        }
        const orderData = {
          customerOrderId,
          currentStatus: initialStatus,
          deliveryMethod: customerOrder.deliveryMethod || "courier",
          vehicleType: customerOrder.vehicleType || null,
          weightUnit: "kg",
          paymentMethod: customerOrder.paymentMethod
          // 🔥 CRITICAL: Copy payment method from customer order
        };
        const newOrder = await this.createOrderManagement(orderData);
        console.log(`\u2705 [ORDER MANAGEMENT] Added customer order ${customerOrderId} to management system with ID ${newOrder.id}`);
        if ((customerOrder.paymentMethod === "wallet_full" || customerOrder.paymentMethod === "wallet_partial") && customerOrder.paymentStatus === "paid") {
          console.log(`\u{1F6AB} [AUTO-APPROVAL] DISABLED for wallet order ${customerOrder.orderNumber} - requires manual financial approval`);
        }
        return newOrder;
      }
