      // 🚀 PERFORMANCE FIX: Backfill NULL weights in order_management table
      // This runs sequentially in batches to avoid connection pool exhaustion
      async backfillOrderWeights(batchSize = 20) {
        console.log("\u{1F3CB}\uFE0F [WEIGHT BACKFILL] Starting weight backfill for orders with NULL total_weight...");
        const ordersNeedingWeight = await db.select({
          id: orderManagement.id,
          customerOrderId: orderManagement.customerOrderId,
          orderNumber: customerOrders.orderNumber
        }).from(orderManagement).innerJoin(customerOrders, eq11(customerOrders.id, orderManagement.customerOrderId)).where(sql8`${orderManagement.totalWeight} IS NULL`).limit(batchSize);
        console.log(`\u{1F3CB}\uFE0F [WEIGHT BACKFILL] Found ${ordersNeedingWeight.length} orders needing weight calculation`);
        let updated = 0;
        let failed = 0;
        for (const order of ordersNeedingWeight) {
          try {
            const weight = await this.calculateOrderWeight(order.customerOrderId);
            if (weight > 0) {
              await db.update(orderManagement).set({ totalWeight: weight.toFixed(3), weightUnit: "kg" }).where(eq11(orderManagement.id, order.id));
              console.log(`\u2705 [WEIGHT BACKFILL] Updated order ${order.orderNumber}: ${weight} kg`);
              updated++;
            } else {
              console.log(`\u26A0\uFE0F [WEIGHT BACKFILL] Order ${order.orderNumber} has 0 weight - skipping`);
            }
          } catch (error) {
            console.error(`\u274C [WEIGHT BACKFILL] Failed to calculate weight for order ${order.orderNumber}:`, error);
            failed++;
          }
        }
        console.log(`\u{1F389} [WEIGHT BACKFILL] Completed: ${updated} updated, ${failed} failed out of ${ordersNeedingWeight.length}`);
        return { updated, failed };
      }
      // Migrate all customer orders to order management system
      async migrateCustomerOrdersToManagement() {
        console.log(`\u{1F504} [MIGRATION] Starting customer orders migration to order management system`);
        const customerOrdersWithoutManagement = await db.select({
          id: customerOrders.id,
          orderNumber: customerOrders.orderNumber,
          status: customerOrders.status,
          paymentStatus: customerOrders.paymentStatus
        }).from(customerOrders).leftJoin(orderManagement, eq11(customerOrders.id, orderManagement.customerOrderId)).where(sql8`${orderManagement.id} IS NULL`);
        console.log(`\u{1F504} [MIGRATION] Found ${customerOrdersWithoutManagement.length} customer orders to migrate`);
        let migratedCount = 0;
        for (const customerOrder of customerOrdersWithoutManagement) {
          try {
            await this.addCustomerOrderToManagement(customerOrder.id);
            migratedCount++;
            console.log(`\u2705 [MIGRATION] Migrated order ${customerOrder.orderNumber} (${migratedCount}/${customerOrdersWithoutManagement.length})`);
          } catch (error) {
            console.error(`\u274C [MIGRATION] Failed to migrate order ${customerOrder.orderNumber}:`, error);
          }
        }
        console.log(`\u{1F389} [MIGRATION] Completed migration: ${migratedCount}/${customerOrdersWithoutManagement.length} orders migrated`);
      }
