      async getAvailableShippingMethods(criteria) {
        let query = db.select().from(shippingRates2).where(eq11(shippingRates2.isActive, true));
        if (criteria.city) {
          query = query.where(
            eq11(shippingRates2.cityName, criteria.city)
          );
        }
        if (criteria.province) {
          query = query.where(
            eq11(shippingRates2.provinceName, criteria.province)
          );
        }
        const availableMethods = await query.orderBy(asc3(shippingRates2.basePrice));
        return availableMethods.filter((method) => {
          if (!method.freeShippingThreshold) return true;
          const threshold = parseFloat(method.freeShippingThreshold);
          return criteria.orderTotal < threshold;
        });
      }
      async calculateShippingCost(criteria) {
        let query = db.select().from(shippingRates2).where(
          and10(
            eq11(shippingRates2.deliveryMethod, criteria.deliveryMethod),
            eq11(shippingRates2.isActive, true)
          )
        );
        if (criteria.city) {
          query = query.where(eq11(shippingRates2.cityName, criteria.city));
        }
        if (criteria.province) {
          query = query.where(eq11(shippingRates2.provinceName, criteria.province));
        }
        const [shippingRate] = await query.limit(1);
        if (!shippingRate) {
          throw new Error("Shipping method not available for this location");
        }
        if (shippingRate.freeShippingThreshold) {
          const threshold = parseFloat(shippingRate.freeShippingThreshold);
          if (criteria.orderTotal >= threshold) {
            return 0;
          }
        }
        let totalCost = parseFloat(shippingRate.basePrice);
        if (shippingRate.pricePerKg && criteria.weight > 0) {
          const weightCost = parseFloat(shippingRate.pricePerKg) * criteria.weight;
          totalCost += weightCost;
        }
        return Math.round(totalCost);
      }
