import { sql as sql21, eq as eq27 } from "drizzle-orm";
async function generateSitemap() {
  const baseUrl = "https://momtazchem.com";
  const urls = [];
  const staticPages = [
    { loc: `${baseUrl}/`, changefreq: "daily", priority: 1 },
    { loc: `${baseUrl}/shop`, changefreq: "daily", priority: 0.9 },
    { loc: `${baseUrl}/blog`, changefreq: "daily", priority: 0.9 },
    { loc: `${baseUrl}/about`, changefreq: "monthly", priority: 0.8 },
    { loc: `${baseUrl}/contact`, changefreq: "monthly", priority: 0.8 },
    { loc: `${baseUrl}/services`, changefreq: "monthly", priority: 0.7 },
    { loc: `${baseUrl}/quote`, changefreq: "weekly", priority: 0.6 }
  ];
  urls.push(...staticPages);
  try {
    const activeProducts = await db.select({
      id: shopProducts.id,
      updatedAt: shopProducts.updatedAt
    }).from(shopProducts).where(sql21`${shopProducts.isActive} = true AND ${shopProducts.visibleInShop} = true AND ${shopProducts.stockQuantity} > 0`);
    activeProducts.forEach((product) => {
      urls.push({
        loc: `${baseUrl}/product-reviews/${product.id}`,
        lastmod: product.updatedAt ? new Date(product.updatedAt).toISOString().split("T")[0] : void 0,
        changefreq: "weekly",
        priority: 0.7
      });
    });
    const allCategories = await db.select().from(shopCategories);
    allCategories.forEach((category) => {
      if (category.slug) {
        urls.push({
          loc: `${baseUrl}/products/${category.slug}`,
          changefreq: "weekly",
          priority: 0.6
        });
      }
    });
    const publishedPosts = await db.select({
      id: blogPosts.id,
      updatedAt: blogPosts.updatedAt,
      publishDate: blogPosts.publishDate
    }).from(blogPosts).where(eq27(blogPosts.status, "published"));
    for (const post of publishedPosts) {
      const translations = await db.select({
        slug: blogPostTranslations.slug,
        language: blogPostTranslations.language,
        updatedAt: blogPostTranslations.updatedAt
      }).from(blogPostTranslations).where(eq27(blogPostTranslations.postId, post.id));
      translations.forEach((translation) => {
        urls.push({
          loc: `${baseUrl}/blog/${translation.slug}`,
          lastmod: translation.updatedAt ? new Date(translation.updatedAt).toISOString().split("T")[0] : post.publishDate ? new Date(post.publishDate).toISOString().split("T")[0] : void 0,
          changefreq: "weekly",
          priority: 0.8
        });
      });
    }
  } catch (error) {
    console.error("Error fetching sitemap data:", error);
  }
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map((url) => `  <url>
    <loc>${url.loc}</loc>${url.lastmod ? `
    <lastmod>${url.lastmod}</lastmod>` : ""}${url.changefreq ? `
    <changefreq>${url.changefreq}</changefreq>` : ""}${url.priority ? `
    <priority>${url.priority}</priority>` : ""}
  </url>`).join("\n")}
</urlset>`;
  return xml;
}

