async function getVendorIdFromSession(req) {
  if (!req.session?.vendorUserId) {
    return null;
  }
  try {
    const vendorUser = await db.select({ vendorId: vendorUsers.vendorId }).from(vendorUsers).where(eq44(vendorUsers.id, req.session.vendorUserId)).limit(1);
    if (vendorUser && vendorUser.length > 0) {
      return vendorUser[0].vendorId;
    }
  } catch (err) {
    console.error("Error fetching vendor ID from session:", err);
  }
  return null;
}
async function verifyVendorOwnsProduct(req, productId) {
  if (req.session?.isAuthenticated && req.session?.adminId) {
    return true;
  }
  const vendorId = await getVendorIdFromSession(req);
  if (!vendorId) {
    return false;
  }
  const product = await storage.getProductById(productId);
  if (!product) {
    return false;
  }
  return product.vendorId === vendorId;
}
