  app2.put("/api/admin/users/:id/password", requireAuth, async (req, res) => {
    try {
      const userId = req.params.id;
      const { newPassword } = req.body;
      if (!userId) {
        return res.status(400).json({
          success: false,
          message: "Invalid user ID"
        });
      }
      if (!newPassword) {
        return res.status(400).json({
          success: false,
          message: "New password is required"
        });
      }
      const newPasswordHash = await bcrypt4.hash(newPassword, 10);
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const result = await pool3.query(`
        UPDATE custom_users 
        SET password_hash = $1
        WHERE id = $2
        RETURNING id, full_name
      `, [newPasswordHash, userId]);
      if (result.rows.length === 0) {
        return res.status(404).json({
          success: false,
          message: "User not found"
        });
      }
      res.json({
        success: true,
        message: "User password updated successfully"
      });
    } catch (error) {
      console.error("Error updating user password:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
  app2.post("/api/admin/users/:id/send-reset-link", requireAuth, async (req, res) => {
    try {
      const userId = req.params.id;
      if (!userId) {
        return res.status(400).json({
          success: false,
          message: "Invalid user ID"
        });
      }
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const result = await pool3.query(`
        SELECT id, full_name, email 
        FROM custom_users 
        WHERE id = $1
      `, [userId]);
      if (result.rows.length === 0) {
        return res.status(404).json({
          success: false,
          message: "User not found"
        });
      }
      const user = result.rows[0];
      const resetToken = Math.random().toString(36).substring(2) + Date.now().toString(36);
      const expiresAt = new Date(Date.now() + 60 * 60 * 1e3);
      await pool3.query(`
        INSERT INTO password_resets (email, token, expires_at, used)
        VALUES ($1, $2, $3, $4)
      `, [user.email, resetToken, expiresAt, false]);
      const resetLink = `${req.protocol}://${req.get("host")}/reset-password?token=${resetToken}`;
      console.log(`Password reset link for ${user.email}: ${resetLink}`);
      res.json({
        success: true,
        message: `Password reset link sent to ${user.email}`,
        resetLink,
        // In production, this would be sent via email
        resetToken
        // For testing purposes
      });
    } catch (error) {
      console.error("Error sending password reset link:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
