  const uploadFlexible = multer({
    storage: imageStorage,
    limits: {
      fileSize: 2 * 1024 * 1024
      // 2MB limit - optimized for web display
    },
    fileFilter: (req, file, cb) => {
      const allowedMimeTypes = [
        "image/jpeg",
        "image/jpg",
        "image/png",
        "image/webp"
      ];
      if (allowedMimeTypes.includes(file.mimetype)) {
        cb(null, true);
      } else {
        cb(new Error("Only JPEG, PNG, and WebP images are allowed for optimal customer display"));
      }
    }
  });
  app2.post("/api/upload", requireProductManagerAuth, (req, res) => {
    const upload3 = uploadFlexible.fields([
      { name: "file", maxCount: 1 },
      { name: "image", maxCount: 1 }
    ]);
    upload3(req, res, async (err) => {
      if (err) {
        console.error("Upload error:", err);
        return res.status(400).json({
          success: false,
          message: err.message
        });
      }
      try {
        const files = req.files;
        const uploadedFile = files?.file?.[0] || files?.image?.[0];
        if (!uploadedFile) {
          return res.status(400).json({
            success: false,
            message: "No file uploaded"
          });
        }
        const s3Service = getAwsS3Service();
        const folder = uploadedFile.fieldname === "image" ? "product-images" : "general-files";
        const uploadResult = await s3Service.uploadPublicFile(
          uploadedFile.buffer,
          uploadedFile.originalname,
          uploadedFile.mimetype,
          folder
        );
        if (!uploadResult.success) {
          return res.status(500).json({
            success: false,
            message: uploadResult.message || "Failed to upload to S3"
          });
        }
        console.log(`\u2705 [S3 UPLOAD] Flexible upload: ${uploadResult.key}`);
        res.json({
          success: true,
          url: uploadResult.url,
          filename: uploadResult.key?.split("/").pop() || uploadedFile.originalname,
          originalName: uploadedFile.originalname,
          size: uploadedFile.size
        });
      } catch (error) {
        console.error("Upload processing error:", error);
        res.status(500).json({
          success: false,
          message: "Failed to process upload"
        });
      }
    });
  });
