  app2.delete("/api/products/:id", requireProductManagerAuth, async (req, res) => {
    try {
      const id2 = parseInt(req.params.id);
      if (isNaN(id2)) {
        return res.status(400).json({
          success: false,
          message: "Invalid product ID"
        });
      }
      const hasOwnership = await verifyVendorOwnsProduct(req, id2);
      if (!hasOwnership) {
        console.log(`\u{1F6AB} [VENDOR SECURITY] Vendor attempted to delete product they dont own: ${id2}`);
        return res.status(403).json({
          success: false,
          message: "\u0634\u0645\u0627 \u0645\u062C\u0627\u0632 \u0628\u0647 \u062D\u0630\u0641 \u0627\u06CC\u0646 \u0645\u062D\u0635\u0648\u0644 \u0646\u06CC\u0633\u062A\u06CC\u062F"
        });
      }
      const productToDelete = await storage.getProductById(id2);
      if (productToDelete) {
        try {
          const shopProducts2 = await shopStorage.getShopProducts();
          const matchingShopProduct = shopProducts2.find(
            (p) => p.barcode === productToDelete.barcode || p.name === productToDelete.name || p.sku === productToDelete.sku
          );
          if (matchingShopProduct) {
            await shopStorage.deleteShopProduct(matchingShopProduct.id);
            console.log(`\u2705 [DELETE-SYNC] Removed matching shop product: ${matchingShopProduct.name} (barcode: ${matchingShopProduct.barcode})`);
          } else {
            console.log(`\u26A0\uFE0F [DELETE-SYNC] No matching shop product found for: ${productToDelete.name} (barcode: ${productToDelete.barcode})`);
          }
        } catch (error) {
          console.log("\u274C [DELETE-SYNC] Error removing from shop:", error);
        }
      }
      try {
        const { KardexSyncMaster: KardexSyncMaster2 } = await Promise.resolve().then(() => (init_kardex_sync_master(), kardex_sync_master_exports));
        const result = await KardexSyncMaster2.smartSyncShopFromKardex();
        console.log(`\u{1F504} Auto-sync completed after deleting product ${id2}:`, result.message);
      } catch (syncError) {
        console.log("Auto-sync failed after deletion:", syncError);
      }
      console.log(`Product ${id2} deleted successfully from both showcase and shop with auto-sync`);
      res.json({ success: true, message: "Product deleted successfully" });
    } catch (error) {
      console.error("Delete product error:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
