  app2.post("/api/ean13/validate", requireAuth, async (req, res) => {
    try {
      const { barcode } = req.body;
      if (!barcode || typeof barcode !== "string") {
        return res.status(400).json({
          success: false,
          message: "Barcode is required"
        });
      }
      if (barcode.length !== 13 || !/^\d+$/.test(barcode)) {
        return res.json({
          success: true,
          valid: false,
          message: "Invalid EAN-13 format"
        });
      }
      let sum4 = 0;
      for (let i = 0; i < 12; i++) {
        const digit = parseInt(barcode[i]);
        sum4 += i % 2 === 0 ? digit : digit * 3;
      }
      const calculatedCheckDigit = (10 - sum4 % 10) % 10;
      const providedCheckDigit = parseInt(barcode[12]);
      const isValid = calculatedCheckDigit === providedCheckDigit;
      res.json({
        success: true,
        valid: isValid,
        checkDigit: calculatedCheckDigit,
        message: isValid ? "Valid EAN-13 barcode" : "Invalid check digit"
      });
    } catch (error) {
      console.error("Error validating EAN-13:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
