  app2.put("/api/admin/users/:id", requireSuperAdmin, async (req, res) => {
    try {
      const { id: id2 } = req.params;
      const { username, email, password, roleId } = req.body;
      let query = `
        UPDATE users 
        SET username = $1, email = $2, role_id = $3, updated_at = NOW()
      `;
      let params = [username, email, roleId];
      if (password && password.trim() !== "") {
        const passwordHash = await bcrypt4.hash(password, 12);
        query += `, password_hash = $4`;
        params.push(passwordHash);
        query += ` WHERE id = $5`;
        params.push(id2);
      } else {
        query += ` WHERE id = $4`;
        params.push(id2);
      }
      query += ` RETURNING id, username, email, role_id, is_active`;
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const result = await pool3.query(query, params);
      if (result.rows.length === 0) {
        return res.status(404).json({ success: false, message: "User not found" });
      }
      res.json({
        success: true,
        user: result.rows[0]
      });
    } catch (error) {
      console.error("Error updating user:", error);
      if (error.code === "23505") {
        res.status(400).json({ success: false, message: "Username or email already exists" });
      } else {
        res.status(500).json({ success: false, message: "Internal server error" });
      }
    }
  });
