  app2.put("/api/custom-users/:id", requireAdmin, async (req, res) => {
    try {
      const { id: id2 } = req.params;
      const { fullName, roleId, isActive, smsNotifications: smsNotifications2, emailNotifications, password } = req.body;
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      let query = `
        UPDATE custom_users 
        SET full_name = $1, role_id = $2, is_active = $3, 
            sms_notifications = $4, email_notifications = $5, updated_at = NOW()
      `;
      let values = [fullName, roleId, isActive, smsNotifications2, emailNotifications];
      if (password) {
        const bcrypt7 = await import("bcryptjs");
        const passwordHash = await bcrypt7.hash(password, 12);
        query += `, password_hash = $6`;
        values.push(passwordHash);
      }
      query += ` WHERE id = $${values.length + 1} RETURNING *`;
      values.push(id2);
      const result = await pool3.query(query, values);
      if (result.rows.length === 0) {
        return res.status(404).json({ success: false, message: "\u06A9\u0627\u0631\u0628\u0631 \u06CC\u0627\u0641\u062A \u0646\u0634\u062F" });
      }
      res.json({
        success: true,
        user: result.rows[0],
        message: "\u06A9\u0627\u0631\u0628\u0631 \u0628\u0627 \u0645\u0648\u0641\u0642\u06CC\u062A \u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC \u0634\u062F"
      });
    } catch (error) {
      console.error("Error updating custom user:", error);
      res.status(500).json({ success: false, message: "\u062E\u0637\u0627 \u062F\u0631 \u0628\u0647\u200C\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06CC \u06A9\u0627\u0631\u0628\u0631" });
    }
  });
