  app2.post("/api/payment/verify", async (req, res) => {
    try {
      const { transactionId, gatewayType, orderId } = req.body;
      if (!transactionId || !gatewayType) {
        return res.status(400).json({
          success: false,
          message: "\u0634\u0646\u0627\u0633\u0647 \u062A\u0631\u0627\u06A9\u0646\u0634 \u0648 \u0646\u0648\u0639 \u062F\u0631\u06AF\u0627\u0647 \u0627\u0644\u0632\u0627\u0645\u06CC \u0627\u0633\u062A"
        });
      }
      console.log(`\u{1F50D} [PAYMENT VERIFICATION] Verifying payment: ${transactionId} (${gatewayType})`);
      const { bankGatewayRouter: bankGatewayRouter2 } = await Promise.resolve().then(() => (init_bank_gateway_router(), bank_gateway_router_exports));
      const verificationResult = await bankGatewayRouter2.verifyPayment(transactionId, gatewayType);
      if (!verificationResult.success) {
        console.log(`\u274C [PAYMENT VERIFICATION] Failed to verify: ${verificationResult.message}`);
        return res.status(500).json(verificationResult);
      }
      if (!verificationResult.verified) {
        console.log(`\u274C [PAYMENT VERIFICATION] Payment not verified: ${transactionId}`);
        return res.status(400).json({
          success: false,
          message: "\u067E\u0631\u062F\u0627\u062E\u062A \u062A\u0623\u06CC\u06CC\u062F \u0646\u0634\u062F"
        });
      }
      if (verificationResult.orderId) {
        const { paymentWorkflow: paymentWorkflow2 } = await Promise.resolve().then(() => (init_payment_workflow(), payment_workflow_exports));
        const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
        const orderResult = await pool3.query(`
          SELECT id, order_number, payment_method 
          FROM customer_orders 
          WHERE id = $1
        `, [verificationResult.orderId]);
        if (orderResult.rows.length > 0) {
          const order = orderResult.rows[0];
          if (order.payment_method === "bank_gateway" && !order.order_number) {
            console.log(`\u{1F3E6} [BANK VERIFICATION] Assigning order number for successful bank payment`);
            const orderNumber2 = await paymentWorkflow2.assignOrderNumberAfterPaymentSuccess(verificationResult.orderId);
            console.log(`\u2705 [BANK VERIFICATION] Order number ${orderNumber2} assigned after successful payment`);
          } else {
            await pool3.query(`
              UPDATE customer_orders 
              SET 
                payment_status = 'paid',
                status = 'confirmed',
                payment_transaction_id = $1,
                updated_at = NOW()
              WHERE id = $2
            `, [transactionId, verificationResult.orderId]);
            console.log(`\u2705 [PAYMENT VERIFICATION] Order ${verificationResult.orderId} payment verified and updated`);
          }
        }
      }
      res.json({
        success: true,
        verified: true,
        message: "\u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0627 \u0645\u0648\u0641\u0642\u06CC\u062A \u062A\u0623\u06CC\u06CC\u062F \u0634\u062F",
        ...verificationResult
      });
    } catch (error) {
      console.error("\u274C [PAYMENT VERIFICATION] Error:", error);
      res.status(500).json({
        success: false,
        message: "\u062E\u0637\u0627 \u062F\u0631 \u062A\u0623\u06CC\u06CC\u062F \u067E\u0631\u062F\u0627\u062E\u062A"
      });
    }
  });
  app2.get("/api/payment/success", async (req, res) => {
    try {
      const { transactionId, orderId, amount, status } = req.query;
      console.log(`\u2705 [PAYMENT SUCCESS] Callback received:`, {
        transactionId,
        orderId,
        amount,
        status
      });
      if (status === "success" && transactionId) {
        const { bankGatewayRouter: bankGatewayRouter2 } = await Promise.resolve().then(() => (init_bank_gateway_router(), bank_gateway_router_exports));
        const verificationResult = await bankGatewayRouter2.verifyPayment(
          transactionId.toString(),
          "auto_detect"
        );
        if (verificationResult.verified) {
          const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
          const orderCheck = await pool3.query(`
            SELECT id, order_number, total_amount, customer_id
            FROM customer_orders 
            WHERE id = $1
          `, [orderId]);
          if (orderCheck.rows.length > 0) {
            const order = orderCheck.rows[0];
            if (!order.order_number) {
              const { OrderManagementStorage: OrderManagementStorage2 } = await Promise.resolve().then(() => (init_order_management_storage(), order_management_storage_exports));
              const orderManagementStorage2 = new OrderManagementStorage2();
              const newOrderNumber = await orderManagementStorage2.generateOrderNumberInTransaction();
              console.log(`\u{1F195} [ORDER NUMBER ASSIGNMENT] Assigning ${newOrderNumber} to successful bank payment order ${orderId}`);
              await pool3.query(`
                UPDATE customer_orders 
                SET 
                  order_number = $1,
                  payment_status = 'paid',
                  status = 'warehouse_pending',
                  payment_transaction_id = $2,
                  updated_at = NOW()
                WHERE id = $3
              `, [newOrderNumber, transactionId, orderId]);
              console.log(`\u2705 [PAYMENT SUCCESS] Order ${orderId} \u2192 ${newOrderNumber} assigned and sent to warehouse`);
              res.redirect(`/payment/success?order=${newOrderNumber}&amount=${order.total_amount}`);
              return;
            } else {
              await pool3.query(`
                UPDATE customer_orders 
                SET 
                  payment_status = 'paid',
                  status = 'warehouse_pending',
                  payment_transaction_id = $1,
                  updated_at = NOW()
                WHERE id = $2
              `, [transactionId, orderId]);
              console.log(`\u2705 [PAYMENT SUCCESS] Order ${order.order_number} marked as paid`);
              res.redirect(`/payment/success?order=${order.order_number}&amount=${order.total_amount}`);
              return;
            }
          }
        }
      }
      res.redirect(`/payment/failed?reason=verification_failed`);
    } catch (error) {
      console.error("\u274C [PAYMENT SUCCESS] Error processing callback:", error);
      res.redirect(`/payment/failed?reason=processing_error`);
    }
  });
  app2.get("/api/payment/cancel", async (req, res) => {
    try {
      const { transactionId, orderId } = req.query;
      console.log(`\u274C [PAYMENT CANCEL] Callback received:`, {
        transactionId,
        orderId
      });
      if (orderId) {
        const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
        const orderCheck = await pool3.query(`
          SELECT id, order_number, customer_id
          FROM customer_orders 
          WHERE id = $1
        `, [orderId]);
        if (orderCheck.rows.length > 0) {
          const order = orderCheck.rows[0];
          if (!order.order_number) {
            console.log(`\u{1F5D1}\uFE0F [PAYMENT CANCEL] Deleting failed bank payment order ${orderId} immediately`);
            try {
              await pool3.query("BEGIN");
              try {
                if (order.customer_id) {
                  try {
                    console.log(`\u{1F6D2} [ABANDONED CART] Creating abandoned cart session for failed payment order ${orderId}`);
                    const orderItems5 = await pool3.query(`
                      SELECT 
                        oi.product_id,
                        oi.quantity,
                        oi.price,
                        oi.total_amount,
                        p.name as product_name
                      FROM order_items oi
                      LEFT JOIN shop_products p ON oi.product_id = p.id
                      WHERE oi.order_id = $1
                    `, [orderId]);
                    if (orderItems5.rows.length > 0) {
                      const cartData = {};
                      let totalValue = 0;
                      let itemCount = 0;
                      for (const item of orderItems5.rows) {
                        cartData[item.product_id] = item.quantity;
                        totalValue += parseFloat(item.total_amount || 0);
                        itemCount += item.quantity;
                      }
                      const { cartStorage: cartStorage2 } = await Promise.resolve().then(() => (init_cart_storage(), cart_storage_exports));
                      const cartSessionId = await cartStorage2.createOrUpdateCartSession({
                        customerId: order.customer_id,
                        sessionId: `failed_payment_${orderId}_${Date.now()}`,
                        cartData,
                        itemCount,
                        totalValue
                      });
                      await cartStorage2.markCartAsAbandonedWithNotification(cartSessionId);
                      await cartStorage2.createNotification({
                        cartSessionId,
                        customerId: order.customer_id,
                        notificationType: "failed_bank_payment",
                        title: "\u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0627\u0646\u06A9\u06CC \u0646\u0627\u0645\u0648\u0641\u0642",
                        message: `\u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0627\u0646\u06A9\u06CC \u0633\u0641\u0627\u0631\u0634 \u0634\u0645\u0627 \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062F. \u0645\u062D\u0635\u0648\u0644\u0627\u062A \u0627\u0646\u062A\u062E\u0627\u0628\u06CC \u062F\u0631 \u0633\u0628\u062F \u062E\u0631\u06CC\u062F \u0634\u0645\u0627 \u0646\u06AF\u0647\u062F\u0627\u0631\u06CC \u0634\u062F\u0647\u200C\u0627\u0646\u062F. \u0628\u0631\u0627\u06CC \u062A\u06A9\u0645\u06CC\u0644 \u062E\u0631\u06CC\u062F \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F.`
                      });
                      console.log(`\u2705 [ABANDONED CART] Created abandoned cart session ${cartSessionId} for failed payment`);
                    }
                  } catch (cartError) {
                    console.error(`\u274C [ABANDONED CART] Failed to create abandoned cart session:`, cartError);
                  }
                }
                await pool3.query(`DELETE FROM order_management WHERE customer_order_id = $1`, [orderId]);
                console.log(`\u{1F5D1}\uFE0F [IMMEDIATE DELETION] Deleted order_management for order ${orderId}`);
                await pool3.query(`DELETE FROM order_items WHERE order_id = $1`, [orderId]);
                console.log(`\u{1F5D1}\uFE0F [IMMEDIATE DELETION] Deleted order_items for order ${orderId}`);
                await pool3.query(`DELETE FROM payment_receipts WHERE customer_order_id = $1`, [orderId]);
                console.log(`\u{1F5D1}\uFE0F [IMMEDIATE DELETION] Deleted payment_receipts for order ${orderId}`);
                await pool3.query(`DELETE FROM customer_orders WHERE id = $1`, [orderId]);
                console.log(`\u{1F5D1}\uFE0F [IMMEDIATE DELETION] Deleted customer_order ${orderId}`);
                await pool3.query("COMMIT");
                console.log(`\u2705 [IMMEDIATE DELETION] Successfully deleted failed bank payment order ${orderId}`);
              } catch (deleteError) {
                await pool3.query("ROLLBACK");
                throw deleteError;
              }
            } catch (deleteError) {
              console.error(`\u274C [IMMEDIATE DELETION] Failed to delete order ${orderId}:`, deleteError);
            }
          } else {
            console.log(`\u{1F504} [PAYMENT CANCEL] Order ${order.order_number} already has order number - keeping for manual review`);
          }
        }
      }
      res.redirect(`/payment/cancelled?order=${orderId}`);
    } catch (error) {
      console.error("\u274C [PAYMENT CANCEL] Error processing callback:", error);
      res.redirect(`/payment/failed?reason=processing_error`);
    }
  });
