  app2.get("/api/admin/whatsapp/customers", requireAuth, async (req, res) => {
    try {
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const { page = 1, limit = 20, search = "" } = req.query;
      const offset = (parseInt(page) - 1) * parseInt(limit);
      let query = `
        SELECT 
          c.id,
          c.first_name,
          c.last_name,
          c.email,
          c.phone,
          c.whatsapp_number,
          COALESCE(c.whatsapp_number, c.phone) as whatsapp_contact,
          c.communication_preference,
          c.created_at,
          c.last_contact_date,
          c.updated_at,
          COUNT(co.id) as total_orders,
          COALESCE(SUM(co.total_amount::numeric), 0) as total_spent
        FROM customers c
        LEFT JOIN customer_orders co ON c.id = co.customer_id
        WHERE (
          (c.whatsapp_number IS NOT NULL AND c.whatsapp_number != '') OR
          (c.phone IS NOT NULL AND c.phone != '')
        )
      `;
      const params = [];
      if (search) {
        query += ` AND (
          c.first_name ILIKE $1 OR 
          c.last_name ILIKE $1 OR 
          c.email ILIKE $1 OR 
          c.phone ILIKE $1 OR
          c.whatsapp_number ILIKE $1
        )`;
        params.push(`%${search}%`);
      }
      query += `
        GROUP BY c.id, c.first_name, c.last_name, c.email, c.phone, 
                 c.whatsapp_number, c.communication_preference, c.created_at, 
                 c.last_contact_date, c.updated_at
        ORDER BY c.created_at DESC
        LIMIT $${params.length + 1} OFFSET $${params.length + 2}
      `;
      params.push(parseInt(limit), offset);
      const customers4 = await pool3.query(query, params);
      let countQuery = `
        SELECT COUNT(*) as total
        FROM customers c
        WHERE (
          (c.whatsapp_number IS NOT NULL AND c.whatsapp_number != '') OR
          (c.phone IS NOT NULL AND c.phone != '')
        )
      `;
      const countParams = [];
      if (search) {
        countQuery += ` AND (
          c.first_name ILIKE $1 OR 
          c.last_name ILIKE $1 OR 
          c.email ILIKE $1 OR 
          c.phone ILIKE $1 OR
          c.whatsapp_number ILIKE $1
        )`;
        countParams.push(`%${search}%`);
      }
      const countResult = await pool3.query(countQuery, countParams);
      const total = parseInt(countResult.rows[0].total);
      res.json({
        success: true,
        data: {
          customers: customers4.rows,
          pagination: {
            page: parseInt(page),
            limit: parseInt(limit),
            total,
            totalPages: Math.ceil(total / parseInt(limit))
          }
        }
      });
    } catch (error) {
      console.error("Error fetching WhatsApp customers:", error);
      res.status(500).json({ success: false, message: "\u062E\u0637\u0627 \u062F\u0631 \u062F\u0631\u06CC\u0627\u0641\u062A \u0644\u06CC\u0633\u062A \u0645\u0634\u062A\u0631\u06CC\u0627\u0646 \u0648\u0627\u062A\u0633\u0627\u067E" });
    }
  });
  app2.get("/api/admin/whatsapp/stats", requireAuth, async (req, res) => {
    try {
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const stats = await pool3.query(`
        SELECT 
          COUNT(*) as total_customers,
          COUNT(CASE WHEN whatsapp_number IS NOT NULL AND whatsapp_number != '' THEN 1 END) as whatsapp_customers,
          COUNT(CASE WHEN communication_preference = 'whatsapp' THEN 1 END) as whatsapp_preferred,
          COUNT(CASE WHEN communication_preference = 'email' THEN 1 END) as email_preferred,
          COUNT(CASE WHEN communication_preference = 'sms' THEN 1 END) as sms_preferred,
          COUNT(CASE WHEN communication_preference = 'phone' THEN 1 END) as phone_preferred
        FROM customers
      `);
      const recentActivity = await pool3.query(`
        SELECT 
          DATE(created_at) as date,
          COUNT(*) as new_customers
        FROM customers 
        WHERE whatsapp_number IS NOT NULL 
          AND whatsapp_number != ''
          AND created_at >= NOW() - INTERVAL '30 days'
        GROUP BY DATE(created_at)
        ORDER BY date DESC
        LIMIT 30
      `);
      res.json({
        success: true,
        data: {
          overview: stats.rows[0],
          recentActivity: recentActivity.rows
        }
      });
    } catch (error) {
      console.error("Error fetching WhatsApp statistics:", error);
      res.status(500).json({ success: false, message: "\u062E\u0637\u0627 \u062F\u0631 \u062F\u0631\u06CC\u0627\u0641\u062A \u0622\u0645\u0627\u0631 \u0648\u0627\u062A\u0633\u0627\u067E" });
    }
  });
