  app2.post("/api/customers/reset-password", async (req, res) => {
    try {
      const { token, newPassword } = req.body;
      if (!token || !newPassword) {
        return res.status(400).json({
          success: false,
          message: "Token and new password are required"
        });
      }
      if (newPassword.length < 6) {
        return res.status(400).json({
          success: false,
          message: "Password must be at least 6 characters"
        });
      }
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const tokenResult = await pool3.query(
        "SELECT email FROM password_resets WHERE token = $1 AND expires_at > NOW() AND used = false",
        [token]
      );
      if (tokenResult.rows.length === 0) {
        return res.status(400).json({
          success: false,
          message: "Invalid or expired token"
        });
      }
      const email = tokenResult.rows[0].email;
      const customer = await customerStorage.getCustomerByEmail(email);
      if (!customer) {
        return res.status(404).json({
          success: false,
          message: "Customer not found"
        });
      }
      await customerStorage.updateCustomerPassword(customer.id, newPassword);
      await pool3.query("DELETE FROM password_resets WHERE email = $1", [email]);
      console.log(`\u2705 Password reset completed for customer: ${email}`);
      res.json({
        success: true,
        message: "Password successfully changed"
      });
    } catch (error) {
      console.error("Error in reset password:", error);
      res.status(500).json({
        success: false,
        message: "Error changing password"
      });
    }
  });
