  app2.get("/api/procedures/documents/:documentId/download", requireAuth, async (req, res) => {
    try {
      const { documentId } = req.params;
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      const docResult = await pool3.query(`
        SELECT file_path, file_name, file_type
        FROM procedure_documents
        WHERE id = $1 AND is_active = true
      `, [documentId]);
      if (docResult.rows.length === 0) {
        return res.status(404).json({ success: false, message: "Document not found" });
      }
      const document = docResult.rows[0];
      await pool3.query(`
        UPDATE procedure_documents 
        SET download_count = download_count + 1, last_downloaded_at = NOW()
        WHERE id = $1
      `, [documentId]);
      if (document.file_path.startsWith("procedure-documents/")) {
        try {
          const s3Service = getAwsS3Service();
          const fileBuffer = await s3Service.getFile(document.file_path);
          res.setHeader("Content-Disposition", `attachment; filename="${document.file_name}"`);
          res.setHeader("Content-Type", document.file_type || "application/octet-stream");
          res.setHeader("Content-Length", fileBuffer.length);
          res.send(fileBuffer);
        } catch (s3Error) {
          console.error("Error downloading from S3:", s3Error);
          return res.status(500).json({
            success: false,
            message: "Failed to download document from S3. Please check AWS permissions."
          });
        }
      } else {
        let filePath = document.file_path;
        if (!path2.isAbsolute(filePath)) {
          filePath = path2.resolve(process.cwd(), filePath);
        }
        if (!fs3.existsSync(filePath)) {
          return res.status(404).json({ success: false, message: "File not found on server" });
        }
        res.setHeader("Content-Disposition", `attachment; filename="${document.file_name}"`);
        res.setHeader("Content-Type", document.file_type || "application/octet-stream");
        res.sendFile(filePath);
      }
    } catch (error) {
      console.error("Error downloading document:", error);
      res.status(500).json({ success: false, message: "Internal server error" });
    }
  });
