  app2.post("/api/admin/seo/api-keys/test", requireAuth, async (req, res) => {
    try {
      const { provider, apiKey } = req.body;
      if (!provider || !apiKey) {
        return res.status(400).json({
          success: false,
          message: "Provider and API key are required"
        });
      }
      let testResult = false;
      let errorMessage = "";
      if (provider === "openai") {
        try {
          const response = await fetch("https://api.openai.com/v1/models", {
            headers: {
              "Authorization": `Bearer ${apiKey}`,
              "Content-Type": "application/json"
            }
          });
          testResult = response.ok;
          if (!testResult) {
            errorMessage = `OpenAI API test failed: ${response.statusText}`;
          }
        } catch (error) {
          errorMessage = `OpenAI API test failed: ${error.message}`;
        }
      } else if (provider === "deepseek") {
        try {
          const response = await fetch("https://api.deepseek.com/v1/models", {
            headers: {
              "Authorization": `Bearer ${apiKey}`,
              "Content-Type": "application/json"
            }
          });
          testResult = response.ok;
          if (!testResult) {
            errorMessage = `DeepSeek API test failed: ${response.statusText}`;
          }
        } catch (error) {
          errorMessage = `DeepSeek API test failed: ${error.message}`;
        }
      }
      res.json({
        success: testResult,
        message: testResult ? `${provider} API key is valid` : errorMessage || `${provider} API key test failed`
      });
    } catch (error) {
      console.error("Error testing API key:", error);
      res.status(500).json({ success: false, message: "Failed to test API key" });
    }
  });
