  app2.post("/api/finance/orders/:id/approve", async (req, res) => {
    try {
      const orderId = parseInt(req.params.id);
      const { notes, receiptAmount } = req.body;
      const adminId2 = 1;
      console.log(`\u2705 [FINANCE] Processing payment approval for order ${orderId} with smart wallet management`);
      const { pool: pool3 } = await Promise.resolve().then(() => (init_db(), db_exports));
      console.log(`\u{1F50D} [FINANCE] Looking up order by order_management.id: ${orderId}`);
      const orderManagementResult = await pool3.query(`
        SELECT om.*, co.payment_method, co.status, co.total_amount, co.currency, co.customer_id, co.order_number
        FROM order_management om
        JOIN customer_orders co ON om.customer_order_id = co.id
        WHERE om.id = $1
      `, [orderId]);
      if (orderManagementResult.rows.length === 0) {
        console.log(`\u274C [FINANCE] Order management ID ${orderId} not found`);
        return res.status(404).json({ success: false, message: "\u0633\u0641\u0627\u0631\u0634 \u06CC\u0627\u0641\u062A \u0646\u0634\u062F - \u0634\u0646\u0627\u0633\u0647 \u0645\u062F\u06CC\u0631\u06CC\u062A \u0633\u0641\u0627\u0631\u0634 \u0646\u0627\u0645\u0639\u062A\u0628\u0631" });
      }
      const orderData = orderManagementResult.rows[0];
      const isTemporaryOrder = orderData.payment_grace_period_start !== null;
      const orderManagementId = orderData.id;
      const customerId = orderData.customer_id;
      const orderTotalAmount = parseFloat(orderData.total_amount);
      const paidAmount = receiptAmount ? parseFloat(receiptAmount) : orderTotalAmount;
      console.log(`\u{1F4CA} [FINANCE] Order details - Management ID: ${orderManagementId}, Customer: ${customerId}, Total: ${orderTotalAmount}, Paid: ${paidAmount}`);
      let walletTransactionMessage = "";
      if (receiptAmount && paidAmount !== orderTotalAmount) {
        const difference = paidAmount - orderTotalAmount;
        if (difference > 0) {
          console.log(`\u{1F4B0} [WALLET] Customer overpaid by ${difference} IQD, crediting to wallet`);
          await walletStorage.creditWallet(
            customerId,
            difference,
            `\u0627\u0636\u0627\u0641\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0633\u0641\u0627\u0631\u0634 ${orderData.order_number || orderData.customer_order_id} - \u0627\u0639\u062A\u0628\u0627\u0631 \u0628\u0647 \u06A9\u06CC\u0641 \u067E\u0648\u0644`,
            "overpayment",
            orderData.customer_order_id,
            adminId2
          );
          walletTransactionMessage = ` - \u0645\u0628\u0644\u063A \u0627\u0636\u0627\u0641\u06CC ${difference.toLocaleString()} \u062F\u06CC\u0646\u0627\u0631 \u0628\u0647 \u06A9\u06CC\u0641 \u067E\u0648\u0644 \u0627\u0636\u0627\u0641\u0647 \u0634\u062F`;
        } else {
          const deficit = Math.abs(difference);
          console.log(`\u{1F4B8} [WALLET] Customer underpaid by ${deficit} IQD, checking wallet balance`);
          const walletBalance = await walletStorage.getWalletBalance(customerId);
          console.log(`\u{1F3E6} [WALLET] Customer wallet balance: ${walletBalance} IQD`);
          if (walletBalance >= deficit) {
            console.log(`\u2705 [WALLET] Deducting ${deficit} IQD from wallet to complete payment`);
            await walletStorage.debitWallet(
              customerId,
              deficit,
              `\u062A\u06A9\u0645\u06CC\u0644 \u067E\u0631\u062F\u0627\u062E\u062A \u0633\u0641\u0627\u0631\u0634 ${orderData.order_number || orderData.customer_order_id} - \u06A9\u0633\u0631 \u0627\u0632 \u06A9\u06CC\u0641 \u067E\u0648\u0644`,
              "payment_completion",
              orderData.customer_order_id,
              adminId2
            );
            walletTransactionMessage = ` - \u0645\u0628\u0644\u063A ${deficit.toLocaleString()} \u062F\u06CC\u0646\u0627\u0631 \u0627\u0632 \u06A9\u06CC\u0641 \u067E\u0648\u0644 \u06A9\u0633\u0631 \u0634\u062F`;
          } else {
            console.log(`\u274C [WALLET] Insufficient wallet balance. Required: ${deficit}, Available: ${walletBalance}`);
            return res.status(400).json({
              success: false,
              message: `\u0645\u0648\u062C\u0648\u062F\u06CC \u06A9\u06CC\u0641 \u067E\u0648\u0644 \u0628\u0631\u0627\u06CC \u062A\u06A9\u0645\u06CC\u0644 \u067E\u0631\u062F\u0627\u062E\u062A \u06A9\u0627\u0641\u06CC \u0646\u06CC\u0633\u062A. \u0645\u0637\u0644\u0648\u0628: ${deficit.toLocaleString()} - \u0645\u0648\u062C\u0648\u062F: ${walletBalance.toLocaleString()} \u062F\u06CC\u0646\u0627\u0631`
            });
          }
        }
      }
      const { orderStatuses: orderStatuses2 } = await Promise.resolve().then(() => (init_order_management_schema(), order_management_schema_exports));
      const isWalletPayment = ["wallet_full", "wallet_partial", "wallet_combined", "wallet"].includes(orderData.payment_method);
      const isOnlinePayment = orderData.payment_method === "online_payment";
      const isStrictGracePeriodOrder = orderData.payment_method === "bank_transfer_grace";
      const isGracePeriodOrder = isStrictGracePeriodOrder && !isWalletPayment && !isOnlinePayment;
      console.log(`\u{1F50D} [FINANCE] Order ${orderData.customer_order_id} payment analysis: method=${orderData.payment_method}, isWallet=${isWalletPayment}, isOnline=${isOnlinePayment}, isGrace=${isGracePeriodOrder}`);
      let targetStatus, statusMessage;
      if (isGracePeriodOrder) {
        targetStatus = "financial_approved";
        statusMessage = (notes || "Grace period payment approved by financial department - awaiting manual warehouse transfer") + walletTransactionMessage;
        console.log(`\u{1F3E6} [GRACE PERIOD] Order ${orderData.customer_order_id} approved but staying in financial_approved - requires manual warehouse transfer`);
      } else {
        targetStatus = orderStatuses2.WAREHOUSE_PENDING;
        statusMessage = (notes || "Payment approved by financial department - moving to warehouse") + walletTransactionMessage;
      }
      const updatedOrder = await orderManagementStorage.updateOrderStatus(
        orderManagementId,
        // Use correct order management ID
        targetStatus,
        adminId2,
        "financial",
        statusMessage
      );
      try {
        await globalSyncService.triggerOrderSync(orderData.customer_order_id, "financial_approved");
        console.log(`\u{1F504} [SYNC] Triggered automatic sync for financial approval - order ${orderData.customer_order_id}`);
      } catch (syncError) {
        console.error(`\u274C [SYNC] Auto-sync failed for financial approval:`, syncError);
      }
      if (isTemporaryOrder) {
        console.log(`\u{1F504} [FINANCE] Converting temporary order ${orderId} to regular order`);
        const { OrderManagementStorage: OrderManagementStorage2 } = await Promise.resolve().then(() => (init_order_management_storage(), order_management_storage_exports));
        const orderManagementStorage2 = new OrderManagementStorage2();
        const newOrderNumber = await orderManagementStorage2.generateOrderNumberInTransaction();
        console.log(`\u{1F522} [FINANCE] Generated order number ${newOrderNumber} for approved grace period order`);
        await pool3.query(`
          UPDATE order_management 
          SET payment_grace_period_start = NULL,
              payment_grace_period_end = NULL,
              is_order_locked = false
          WHERE id = $1
        `, [orderManagementId]);
        await pool3.query(`
          UPDATE customer_orders 
          SET status = 'confirmed',
              payment_status = 'paid',
              order_number = $2
          WHERE id = $1
        `, [orderData.customer_order_id, newOrderNumber]);
        console.log(`\u2705 [FINANCE] Order ${orderManagementId} (Customer Order ${orderData.customer_order_id}) converted from temporary to regular order with number ${newOrderNumber} and moved to warehouse`);
        res.json({
          success: true,
          order: updatedOrder,
          orderNumber: newOrderNumber,
          message: `\u0633\u0641\u0627\u0631\u0634 \u0645\u0648\u0642\u062A \u062A\u0627\u06CC\u06CC\u062F \u0634\u062F \u0648 \u0634\u0645\u0627\u0631\u0647 ${newOrderNumber} \u062F\u0631\u06CC\u0627\u0641\u062A \u06A9\u0631\u062F. \u0622\u0645\u0627\u062F\u0647 \u0628\u0631\u0631\u0633\u06CC \u0627\u0646\u0628\u0627\u0631 \u0627\u0633\u062A` + walletTransactionMessage,
          walletTransaction: walletTransactionMessage.length > 0
        });
      } else {
        let orderNumber2 = orderData.order_number;
        if (!orderNumber2) {
          console.log(`\u{1F522} [FINANCE] Assigning order number to regular order ${orderData.customer_order_id}`);
          const { OrderManagementStorage: OrderManagementStorage2 } = await Promise.resolve().then(() => (init_order_management_storage(), order_management_storage_exports));
          const orderManagementStorage2 = new OrderManagementStorage2();
          orderNumber2 = await orderManagementStorage2.generateOrderNumberInTransaction();
          await pool3.query(`
            UPDATE customer_orders 
            SET order_number = $2
            WHERE id = $1
          `, [orderData.customer_order_id, orderNumber2]);
          console.log(`\u2705 [FINANCE] Regular order ${orderManagementId} assigned order number ${orderNumber2}`);
        }
        console.log(`\u2705 [FINANCE] Regular order ${orderManagementId} (Customer Order ${orderData.customer_order_id}) approved and moved to warehouse department`);
        res.json({
          success: true,
          order: updatedOrder,
          orderNumber: orderNumber2,
          message: "\u067E\u0631\u062F\u0627\u062E\u062A \u062A\u0627\u06CC\u06CC\u062F \u0634\u062F \u0648 \u0622\u0645\u0627\u062F\u0647 \u0628\u0631\u0631\u0633\u06CC \u0627\u0646\u0628\u0627\u0631 \u0627\u0633\u062A" + walletTransactionMessage,
          walletTransaction: walletTransactionMessage.length > 0
        });
      }
    } catch (error) {
      console.error("Error approving financial order:", error);
      res.status(500).json({ success: false, message: "\u062E\u0637\u0627 \u062F\u0631 \u062A\u0627\u06CC\u06CC\u062F \u067E\u0631\u062F\u0627\u062E\u062A: " + error.message });
    }
  });
