  async function calculateOrderTaxes(subtotal) {
    try {
      console.log("\u{1F4B0} [TAX] Calculating taxes for subtotal:", subtotal);
      const taxSettingsList = await db.select().from(taxSettings).where(eq44(taxSettings.isEnabled, true));
      console.log("\u{1F4B0} [TAX] Found tax settings:", taxSettingsList);
      const vatSetting = taxSettingsList.find((setting) => setting.type === "vat");
      const dutiesSetting = taxSettingsList.find((setting) => setting.type === "duties");
      const vatRate = vatSetting ? parseFloat(vatSetting.rate) : 0;
      const dutiesRate = dutiesSetting ? parseFloat(dutiesSetting.rate) : 0;
      const vatAmount = vatRate > 0 ? subtotal * vatRate : 0;
      const dutiesAmount = dutiesRate > 0 ? subtotal * dutiesRate : 0;
      const result = {
        vatAmount: parseFloat(vatAmount.toFixed(2)),
        dutiesAmount: parseFloat(dutiesAmount.toFixed(2)),
        vatRate: vatSetting ? parseFloat(vatSetting.rate) * 100 : 0,
        // Return as percentage (6.00 for 6%)
        dutiesRate: dutiesSetting ? parseFloat(dutiesSetting.rate) * 100 : 0,
        // Return as percentage
        vatRateDecimal: vatRate,
        // For internal calculations (0.06 for 6%)
        dutiesRateDecimal: dutiesRate
        // For internal calculations
      };
      console.log("\u{1F4B0} [TAX] Tax calculation result:", result);
      return result;
    } catch (error) {
      console.error("\u274C Error calculating taxes:", error);
      return {
        vatAmount: 0,
        dutiesAmount: 0,
        vatRate: 0,
        dutiesRate: 0,
        vatRateDecimal: 0,
        dutiesRateDecimal: 0
      };
    }
  }
