  app2.post("/api/financial/calculate-vat", async (req, res) => {
    try {
      const { orderItems: orderItems5, orderTotal, shippingCost, customerRegion } = req.body;
      const [currentVat] = await db.select().from(vatSettings).where(and33(
        eq44(vatSettings.isActive, true),
        eq44(vatSettings.vatEnabled, true)
      )).orderBy(desc25(vatSettings.effectiveDate)).limit(1);
      if (!currentVat) {
        return res.json({
          success: true,
          vatAmount: 0,
          vatRate: 0,
          taxableAmount: 0,
          totalWithVat: orderTotal + (shippingCost || 0),
          breakdown: {
            productVat: 0,
            shippingVat: 0,
            exemptAmount: orderTotal
          }
        });
      }
      const applicableRegions = currentVat.applicableRegions || [];
      if (applicableRegions.length > 0 && !applicableRegions.includes(customerRegion)) {
        return res.json({
          success: true,
          vatAmount: 0,
          vatRate: parseFloat(currentVat.vatRate),
          taxableAmount: 0,
          totalWithVat: orderTotal + (shippingCost || 0),
          breakdown: {
            productVat: 0,
            shippingVat: 0,
            exemptAmount: orderTotal
          }
        });
      }
      const exemptCategories = currentVat.exemptCategories || [];
      const exemptProductIds = currentVat.exemptProductIds || [];
      let taxableAmount = 0;
      let exemptAmount = 0;
      for (const item of orderItems5) {
        const isExempt = exemptCategories.includes(item.category) || exemptProductIds.includes(item.productId);
        if (isExempt) {
          exemptAmount += item.totalPrice;
        } else {
          taxableAmount += item.totalPrice;
        }
      }
      if (currentVat.minimumTaxableAmount && taxableAmount < parseFloat(currentVat.minimumTaxableAmount)) {
        taxableAmount = 0;
        exemptAmount = orderTotal;
      }
      const vatRate = parseFloat(currentVat.vatRate) / 100;
      const productVat = taxableAmount * vatRate;
      const shippingVat = currentVat.shippingTaxable ? (shippingCost || 0) * vatRate : 0;
      const totalVat = productVat + shippingVat;
      const totalWithVat = orderTotal + (shippingCost || 0) + totalVat;
      res.json({
        success: true,
        vatAmount: totalVat,
        vatRate: parseFloat(currentVat.vatRate),
        taxableAmount,
        totalWithVat,
        breakdown: {
          productVat,
          shippingVat,
          exemptAmount,
          taxableProductAmount: taxableAmount,
          vatDisplayName: currentVat.vatDisplayName,
          vatNumber: currentVat.vatNumber
        }
      });
    } catch (error) {
      console.error("Error calculating VAT:", error);
      res.status(500).json({ success: false, message: "\u062E\u0637\u0627 \u062F\u0631 \u0645\u062D\u0627\u0633\u0628\u0647 \u0645\u0627\u0644\u06CC\u0627\u062A" });
    }
  });
