  app2.post("/api/wallet/force-sync/:customerId", async (req, res) => {
    try {
      const customerId = parseInt(req.params.customerId);
      console.log(`\u{1F504} [WALLET SYNC] Force syncing wallet for customer ${customerId}`);
      const directWallet = await customerDb.select().from(customerWallets).where(eq44(customerWallets.customerId, customerId));
      const allTransactions = await customerDb.select().from(walletTransactions).where(eq44(walletTransactions.customerId, customerId)).orderBy(walletTransactions.createdAt);
      let calculatedBalance = 0;
      for (const transaction of allTransactions) {
        const amount = parseFloat(transaction.amount);
        if (transaction.transactionType === "credit") {
          calculatedBalance += amount;
        } else if (transaction.transactionType === "debit") {
          calculatedBalance -= amount;
        }
      }
      let wallet;
      if (directWallet.length === 0 && calculatedBalance !== 0) {
        console.log(`\u{1F195} [WALLET SYNC] Creating missing wallet for customer ${customerId}`);
        wallet = await walletStorage.createWallet({
          customerId,
          balance: calculatedBalance.toString(),
          currency: "IQD",
          status: "active"
        });
      } else if (directWallet.length > 0) {
        const currentBalance = parseFloat(directWallet[0].balance);
        if (Math.abs(currentBalance - calculatedBalance) > 0.01) {
          console.log(`\u{1F504} [WALLET SYNC] Updating balance from ${currentBalance} to ${calculatedBalance}`);
          wallet = await walletStorage.updateWalletBalance(directWallet[0].id, calculatedBalance);
        } else {
          wallet = directWallet[0];
        }
      }
      const freshSummary = await walletStorage.getCustomerWalletSummary(customerId);
      const syncResult = {
        customerId,
        timestamp: (/* @__PURE__ */ new Date()).toISOString(),
        beforeSync: {
          walletExists: directWallet.length > 0,
          walletBalance: directWallet.length > 0 ? parseFloat(directWallet[0].balance) : 0,
          transactionCount: allTransactions.length
        },
        calculatedBalance,
        afterSync: {
          wallet,
          summary: freshSummary
        },
        actions: {
          walletCreated: directWallet.length === 0 && calculatedBalance !== 0,
          balanceUpdated: directWallet.length > 0 && Math.abs(parseFloat(directWallet[0].balance) - calculatedBalance) > 0.01,
          alreadyInSync: directWallet.length > 0 && Math.abs(parseFloat(directWallet[0].balance) - calculatedBalance) <= 0.01
        }
      };
      console.log(`\u2705 [WALLET SYNC] Sync completed:`, JSON.stringify(syncResult, null, 2));
      res.json({
        success: true,
        message: "Wallet synchronization completed",
        data: syncResult
      });
    } catch (error) {
      console.error("\u{1F504} [WALLET SYNC] Error during sync:", error);
      res.status(500).json({
        success: false,
        message: "Wallet synchronization failed",
        error: error.message
      });
    }
  });
