  const generateServerSideEAN13Barcode = async (productName, category) => {
    const countryCode = "864";
    const companyCode = "96771";
    let attempts = 0;
    const maxAttempts = 100;
    let productCode = "";
    while (attempts < maxAttempts) {
      const randomCode = Math.floor(1e3 + Math.random() * 9e3).toString();
      const testBarcode12 = countryCode + companyCode + randomCode;
      const testCheckDigit = calculateEAN13CheckDigit2(testBarcode12);
      const testBarcode = testBarcode12 + testCheckDigit;
      const existingShowcase = await db.select().from(showcaseProducts).where(eq44(showcaseProducts.barcode, testBarcode));
      const existingShop = await db.select().from(shopProducts).where(eq44(shopProducts.barcode, testBarcode));
      if (existingShowcase.length === 0 && existingShop.length === 0) {
        productCode = randomCode;
        break;
      }
      attempts++;
    }
    if (!productCode) {
      productCode = Date.now().toString().slice(-4);
    }
    const barcode12 = countryCode + companyCode + productCode;
    const checkDigit = calculateEAN13CheckDigit2(barcode12);
    const fullBarcode = barcode12 + checkDigit;
    console.log("Server-side barcode generation:", {
      productName,
      category,
      countryCode,
      companyCode,
      productCode,
      barcode12,
      checkDigit,
      fullBarcode,
      length: fullBarcode.length
    });
    return fullBarcode;
  };
  const calculateEAN13CheckDigit2 = (barcode12) => {
    let sum4 = 0;
    for (let i = 0; i < 12; i++) {
      const digit = parseInt(barcode12[i]);
      sum4 += i % 2 === 0 ? digit : digit * 3;
    }
    const checkDigit = (10 - sum4 % 10) % 10;
    return checkDigit.toString();
  };
