  app2.post("/api/finance/process-missed-wallet-transactions", requireAuth, async (req, res) => {
    try {
      const { customerStorage: customerStorage2 } = await Promise.resolve().then(() => (init_customer_storage(), customer_storage_exports));
      console.log(`\u{1F50D} [MISSED TRANSACTIONS] Searching for orders with unprocessed wallet differences...`);
      const ordersWithMissedTransactions = await db.select({
        orderManagementId: orderManagement.id,
        customerOrderId: orderManagement.customerOrderId,
        orderNumber: customerOrders.orderNumber,
        customerId: customerOrders.customerId,
        totalAmount: customerOrders.totalAmount,
        receiptAmount: paymentReceipts.receiptAmount,
        financialNotes: orderManagement.financialNotes,
        currentStatus: orderManagement.currentStatus
      }).from(orderManagement).innerJoin(customerOrders, eq44(orderManagement.customerOrderId, customerOrders.id)).innerJoin(paymentReceipts, eq44(paymentReceipts.customerOrderId, customerOrders.id)).where(
        and33(
          isNotNull3(paymentReceipts.receiptAmount),
          // Has receipt amount
          inArray4(orderManagement.currentStatus, ["warehouse_pending", "warehouse_processing", "warehouse_verified"]),
          // Already in warehouse
          // Financial notes don't indicate wallet transaction was processed
          eq44(orderManagement.financialNotes, "Auto-sync status correction - fixed stuck order")
        )
      );
      console.log(`\u{1F4CA} [MISSED TRANSACTIONS] Found ${ordersWithMissedTransactions.length} orders with potential missed wallet transactions`);
      let processedCount = 0;
      let totalCredited = 0;
      let totalDebited = 0;
      const processedOrders = [];
      for (const orderData of ordersWithMissedTransactions) {
        try {
          const orderTotal = parseFloat(orderData.totalAmount);
          const receiptAmount = parseFloat(orderData.receiptAmount);
          const difference = receiptAmount - orderTotal;
          console.log(`\u{1F4B0} [PROCESSING] Order ${orderData.orderNumber}: Total=${orderTotal}, Receipt=${receiptAmount}, Difference=${difference}`);
          if (Math.abs(difference) > 0.01) {
            if (difference > 0) {
              await customerStorage2.addWalletBalance(
                orderData.customerId,
                difference,
                `\u062A\u0635\u062D\u06CC\u062D: \u0627\u0636\u0627\u0641\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0633\u0641\u0627\u0631\u0634 ${orderData.orderNumber} - \u0645\u0639\u0627\u0644\u062C\u0647 \u0628\u0623\u062B\u0631 \u0631\u062C\u0639\u06CC`
              );
              totalCredited += difference;
              console.log(`\u2705 [CREDITED] ${difference} IQD credited to customer ${orderData.customerId} wallet for order ${orderData.orderNumber}`);
            } else {
              const deficit = Math.abs(difference);
              const walletBalance = await customerStorage2.getWalletBalance(orderData.customerId);
              if (walletBalance >= deficit) {
                await customerStorage2.deductWalletBalance(
                  orderData.customerId,
                  deficit,
                  `\u062A\u0635\u062D\u06CC\u062D: \u062A\u06A9\u0645\u06CC\u0644 \u067E\u0631\u062F\u0627\u062E\u062A \u0633\u0641\u0627\u0631\u0634 ${orderData.orderNumber} - \u0645\u0639\u0627\u0644\u062C\u0647 \u0628\u0623\u062B\u0631 \u0631\u062C\u0639\u06CC`
                );
                totalDebited += deficit;
                console.log(`\u2705 [DEBITED] ${deficit} IQD debited from customer ${orderData.customerId} wallet for order ${orderData.orderNumber}`);
              } else {
                console.log(`\u26A0\uFE0F [INSUFFICIENT BALANCE] Customer ${orderData.customerId} wallet balance ${walletBalance} insufficient for deficit ${deficit} on order ${orderData.orderNumber}`);
              }
            }
            const updatedNotes = `${orderData.financialNotes}

\u{1F527} \u062A\u0635\u062D\u06CC\u062D \u0645\u0639\u0627\u0644\u062C\u0629 \u0627\u0644\u0645\u062D\u0641\u0638\u0629 \u0628\u0623\u062B\u0631 \u0631\u062C\u0639\u06CC: ${difference > 0 ? `+${difference}` : difference} \u062F\u06CC\u0646\u0627\u0631 \u0645\u0639\u0627\u0644\u062C`;
            await db.update(orderManagement).set({ financialNotes: updatedNotes }).where(eq44(orderManagement.id, orderData.orderManagementId));
            processedOrders.push({
              orderNumber: orderData.orderNumber,
              difference,
              action: difference > 0 ? "credited" : "debited",
              amount: Math.abs(difference)
            });
            processedCount++;
          } else {
            console.log(`\u2139\uFE0F [NO DIFFERENCE] Order ${orderData.orderNumber} has no meaningful amount difference`);
          }
        } catch (error) {
          console.error(`\u274C [ERROR] Failed to process wallet transaction for order ${orderData.orderNumber}:`, error);
        }
      }
      console.log(`\u2705 [SUMMARY] Processed ${processedCount} orders: ${totalCredited.toFixed(2)} IQD credited, ${totalDebited.toFixed(2)} IQD debited`);
      res.json({
        success: true,
        message: `\u0645\u0639\u0627\u0644\u062C\u0629 ${processedCount} \u0637\u0644\u0628 \u0628\u0623\u062B\u0631 \u0631\u062C\u0639\u06CC - \u0645\u062C\u0645\u0648\u0639 \u0627\u0644\u0625\u064A\u062F\u0627\u0639: ${totalCredited.toFixed(2)} \u062F\u064A\u0646\u0627\u0631\u060C \u0645\u062C\u0645\u0648\u0639 \u0627\u0644\u062E\u0635\u0645: ${totalDebited.toFixed(2)} \u062F\u064A\u0646\u0627\u0631`,
        processedCount,
        totalCredited,
        totalDebited,
        processedOrders
      });
    } catch (error) {
      console.error("Error processing missed wallet transactions:", error);
      res.status(500).json({
        success: false,
        message: "\u062E\u0637\u0627 \u0641\u064A \u0645\u0639\u0627\u0644\u062C\u0629 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u062D\u0641\u0638\u0629 \u0627\u0644\u0645\u0641\u0642\u0648\u062F\u0629",
        error: error instanceof Error ? error.message : "Unknown error"
      });
    }
  });
  app2.get("/api/finance/missed-wallet-transactions", requireAuth, async (req, res) => {
    try {
      console.log("\u{1F50D} [DEBUG] Starting missed wallet transactions check...");
      const ordersWithPotentialIssues = await db.select({
        orderManagementId: orderManagement.id,
        customerOrderId: orderManagement.customerOrderId,
        orderNumber: customerOrders.orderNumber,
        customerId: customerOrders.customerId,
        totalAmount: customerOrders.totalAmount,
        receiptAmount: paymentReceipts.receiptAmount,
        financialNotes: orderManagement.financialNotes,
        currentStatus: orderManagement.currentStatus,
        createdAt: customerOrders.createdAt
      }).from(orderManagement).innerJoin(customerOrders, eq44(orderManagement.customerOrderId, customerOrders.id)).innerJoin(paymentReceipts, eq44(paymentReceipts.customerOrderId, customerOrders.id)).where(
        and33(
          isNotNull3(paymentReceipts.receiptAmount),
          // Has receipt amount
          inArray4(orderManagement.currentStatus, ["warehouse_pending", "warehouse_processing", "warehouse_verified"]),
          // Already in warehouse
          // Financial notes indicate auto-sync correction without wallet processing
          eq44(orderManagement.financialNotes, "Auto-sync status correction - fixed stuck order")
        )
      ).orderBy(customerOrders.createdAt);
      const ordersWithDifferences = ordersWithPotentialIssues.map((order) => {
        const orderTotal = parseFloat(order.totalAmount);
        const receiptAmount = parseFloat(order.receiptAmount);
        const difference = receiptAmount - orderTotal;
        return {
          ...order,
          orderTotal,
          receiptAmount,
          difference,
          hasDifference: Math.abs(difference) > 0.01,
          transactionType: difference > 0 ? "overpayment" : difference < 0 ? "underpayment" : "exact"
        };
      }).filter((order) => order.hasDifference);
      console.log(`\u{1F50D} [MISSED TRANSACTIONS] Found ${ordersWithDifferences.length} orders with unprocessed wallet differences`);
      res.json({
        success: true,
        orders: ordersWithDifferences,
        summary: {
          totalOrders: ordersWithDifferences.length,
          overpayments: ordersWithDifferences.filter((o) => o.difference > 0).length,
          underpayments: ordersWithDifferences.filter((o) => o.difference < 0).length,
          totalOverpaid: ordersWithDifferences.filter((o) => o.difference > 0).reduce((sum4, o) => sum4 + o.difference, 0),
          totalUnderpaid: Math.abs(ordersWithDifferences.filter((o) => o.difference < 0).reduce((sum4, o) => sum4 + o.difference, 0))
        }
      });
    } catch (error) {
      console.error("Error fetching missed wallet transactions:", error);
      res.status(500).json({
        success: false,
        message: "\u062E\u0637\u0627 \u0641\u064A \u062C\u0644\u0628 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0627\u062A \u0627\u0644\u0645\u062D\u0641\u0638\u0629 \u0627\u0644\u0645\u0641\u0642\u0648\u062F\u0629",
        error: error instanceof Error ? error.message : "Unknown error"
      });
    }
  });
