// server/vendor-middleware.ts
function requireVendorAuth(req, res, next) {
  if (!req.session?.vendorUserId) {
    return res.status(401).json({
      success: false,
      message: "Vendor authentication required"
    });
  }
  next();
}
async function loadVendorUser(req, res, next) {
  try {
    const vendorUserId = req.session?.vendorUserId;
    if (!vendorUserId) {
      return res.status(401).json({
        success: false,
        message: "Vendor authentication required"
      });
    }
    const vendorUser = await vendorStorage.getVendorUserById(vendorUserId);
    if (!vendorUser || !vendorUser.isActive) {
      delete req.session.vendorUserId;
      return res.status(401).json({
        success: false,
        message: "Vendor user not found or inactive"
      });
    }
    if (vendorUser.lockedUntil && new Date(vendorUser.lockedUntil) > /* @__PURE__ */ new Date()) {
      return res.status(403).json({
        success: false,
        message: "Account is temporarily locked due to multiple failed login attempts"
      });
    }
    const vendor = await vendorStorage.getVendorById(vendorUser.vendorId);
    if (!vendor || !vendor.isActive || !vendor.isApproved) {
      return res.status(403).json({
        success: false,
        message: "Vendor account is not active or not approved"
      });
    }
    req.vendorUser = {
      id: vendorUser.id,
      vendorId: vendorUser.vendorId,
      username: vendorUser.username,
      email: vendorUser.email,
      role: vendorUser.role,
      permissions: vendorUser.permissions
    };
    next();
  } catch (error) {
    console.error("Error loading vendor user:", error);
    return res.status(500).json({
      success: false,
      message: "Error loading vendor user information"
    });
  }
}
function requireVendorPermission(permission) {
  return (req, res, next) => {
    if (!req.vendorUser) {
      return res.status(401).json({
        success: false,
        message: "Vendor authentication required"
      });
    }
    if (req.vendorUser.role === "vendor_owner") {
      return next();
    }
    const permissions = req.vendorUser.permissions || [];
    if (!permissions.includes(permission)) {
      return res.status(403).json({
        success: false,
        message: `Permission denied: ${permission} required`
      });
    }
    next();
  };
}
function requireVendorRole(allowedRoles) {
  const roles = Array.isArray(allowedRoles) ? allowedRoles : [allowedRoles];
  return (req, res, next) => {
    if (!req.vendorUser) {
      return res.status(401).json({
        success: false,
        message: "Vendor authentication required"
      });
    }
    if (!roles.includes(req.vendorUser.role)) {
      return res.status(403).json({
        success: false,
        message: `Access denied: requires one of these roles: ${roles.join(", ")}`
      });
    }
    next();
  };
}
var vendorAuth = [requireVendorAuth, loadVendorUser];
var vendorProductAuth = [
  requireVendorAuth,
  loadVendorUser,
  requireVendorPermission("manage_products")
];
var vendorOwnerAuth = [
  requireVendorAuth,
  loadVendorUser,
  requireVendorRole("vendor_owner")
];

