        notificationType: type === "first" ? "\u06CC\u0627\u062F\u0622\u0648\u0631\u06CC \u0627\u0648\u0644" : "\u06CC\u0627\u062F\u0622\u0648\u0631\u06CC \u062F\u0648\u0645"
